import * as fs from 'node:fs';
import { webcrypto } from 'node:crypto';
import * as os from 'node:os';
import * as path from 'node:path';
import { DbError } from './core.js';
import { wireConn, type WireClient } from './conn.js';
import { Db } from './db.js';
import { Closed, Refused, StateStoreClient, Timeout, WireError } from './wire/node/StateStore.js';

export * from './core.js';
export * from './db.js';
export * from './define.js';

// node 18 has no global WebCrypto; ULIDs need getRandomValues
if (!globalThis.crypto) (globalThis as { crypto: unknown }).crypto = webcrypto;

export interface OpenOptions {
  /** `host:port` of a state.store that takes this Hello (a dev store: `ce-db-dev-store`). Default `$CE_DB_STORE`, else
   *  this machine's state.store by name. */
  store?: string;
  /** The hex grant for the app. Default `$CE_DB_CAP`, `$STATE_STORE_CAP`, then `~/.config/ce-state/<app>.cap`. */
  cap?: string;
  /** The Hello token. Default: empty for `store`, this node's self proof by name. */
  token?: Uint8Array;
}

function capFor(app: string, o: OpenOptions): string {
  const fromFile = () => {
    try {
      return fs.readFileSync(path.join(os.homedir(), '.config', 'ce-state', `${app}.cap`), 'utf8').trim();
    } catch {
      return '';
    }
  };
  return (o.cap ?? process.env.CE_DB_CAP ?? process.env.STATE_STORE_CAP ?? fromFile()).trim();
}

/** Open `app`: the connection is made at once (2 s deadline), so a store that is not there fails here, typed. */
export async function open(app: string, o: OpenOptions = {}): Promise<Db> {
  if (!/^[A-Za-z0-9._-]{1,64}$/.test(app)) throw new DbError({ kind: 'Invalid', field: 'app', why: '1..=64 of [A-Za-z0-9._-]' });
  const cap = capFor(app, o);
  if (!cap) throw new DbError({ kind: 'Refused', need: `a grant for ${app}: CE_DB_CAP, STATE_STORE_CAP or ~/.config/ce-state/${app}.cap` });
  const store = o.store ?? process.env.CE_DB_STORE;
  let label = 'state.store by name';
  let connect: () => Promise<WireClient>;
  if (store) {
    const i = store.lastIndexOf(':');
    const host = store.slice(0, i);
    const port = Number(store.slice(i + 1));
    label = store;
    connect = async () => {
      const c = await StateStoreClient.connect({ host, port, token: o.token ?? new Uint8Array(), waitMs: 2000 });
      c.conn.deadlineMs = 8000;
      return c as unknown as WireClient;
    };
  } else {
    connect = async () => (await StateStoreClient.byName(o.token)) as unknown as WireClient;
  }
  const conn = wireConn(connect, cap, { Refused, WireError }, label);
  // fail fast: dial now
  try {
    await conn.schema(app);
  } catch (e) {
    if (e instanceof DbError && e.info.kind === 'Unavailable') throw e;
  }
  void Closed;
  void Timeout;
  return new Db(app, conn);
}
